<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import QRCode from 'qrcode'
import ProofThumb from './ProofThumb.vue'
import { isUnreadNotice } from './notice.js'
import { categoryOptions, filterProducts } from '../../shared/categories.js'
const tab = ref('shop'), token = ref(localStorage.getItem('cym-token') || ''), me = ref(null), products = ref([]), orders = ref([]), addresses = ref([]), transactions = ref([]), team = ref([]), message = ref(''), selected = ref(null), qr = ref(''), mode = ref('login'), unreadCount = ref(0)
const category = ref('')
const categories = computed(() => [{ value: '', label: '全部' }, ...categoryOptions(products.value).map(label => ({ value: label, label }))])
const filteredProducts = computed(() => filterProducts(products.value, category.value))
const params = new URLSearchParams(location.hash.split('?')[1] || location.search)
const form = ref({ phone: '', username: '', password: '', alipay_account:'', invite_code: params.get('transfer_invite') || '' })
if (form.value.invite_code) { mode.value = 'register'; tab.value = 'login' }
const address = ref({ contact_name:'',contact_phone:'',province:'',city:'',district:'',detail:'' }), transfer = ref({ phone:'',amount:'',password:'' }), addressId = ref(''), variant = ref(''), busy = ref(false)
const pendingProduct=ref(null)
const earnings=ref({total_reward:'0.00'}), withdrawals=ref([]), withdrawal=ref({amount:'',account_name:'',alipay_account:'',password:''}), withdrawalId=ref(crypto.randomUUID()), alipayStatus=ref({masked:''})
const withdrawalPreview=computed(()=>{const n=Number(withdrawal.value.amount);return Number.isSafeInteger(n)&&n>=50&&n%50===0?{fee:(n*0.06).toFixed(2),net:(n*0.94).toFixed(2)}:null})
const purchaseId = ref(crypto.randomUUID()), transferId = ref(crypto.randomUUID())
async function api(path, opts = {}) { const response = await fetch('/api' + path, { ...opts, headers: { 'Content-Type': 'application/json', ...(token.value ? { Authorization: `Bearer ${token.value}` } : {}), ...opts.headers }, body: opts.body ? JSON.stringify(opts.body) : undefined }); const data = await response.json(); if (!response.ok) throw new Error(data.message || '操作失败'); return data.data ?? data }
function notify(error) { message.value = error?.message || error; setTimeout(() => message.value = '', 3500) }
async function refresh() { try { products.value = await api('/products'); if (token.value) { me.value = await api('/me'); [orders.value, addresses.value, transactions.value, team.value,earnings.value,withdrawals.value,alipayStatus.value] = await Promise.all(['/orders','/addresses','/transactions','/team','/team/earnings','/withdrawals','/account/alipay'].map(x => api(x))); unreadCount.value = (await api('/orders/unread-count')).count; addressId.value = addresses.value[0]?.id || '' } } catch(e) { notify(e) } }
async function refreshNotices() { if (!token.value) return; try { const [list, unread] = await Promise.all([api('/orders'), api('/orders/unread-count')]); orders.value = list; unreadCount.value = unread.count } catch { /* 后台暂不可用时保留上次状态，下次重试 */ } }
async function readNotice(order) { if (Number(order.notice_read)) return; try { await api('/orders/'+order.id+'/read',{method:'PUT'}); order.notice_read=1; unreadCount.value=(await api('/orders/unread-count')).count } catch(e) { notify(e) } }
async function confirmReceipt(order) { if (busy.value || !window.confirm('确认已收到商品？')) return; busy.value=true; try { await api('/orders/'+order.id+'/confirm',{method:'PUT',body:{}}); await refreshNotices(); notify('已确认收货') } catch(e) { notify(e) } finally { busy.value=false } }
async function login() { try { const result = await api('/auth/' + mode.value, { method:'POST', body:form.value }); token.value = result.token; localStorage.setItem('cym-token', token.value); await refresh(); tab.value = 'shop' } catch(e) { notify(e) } }
function logout() { localStorage.removeItem('cym-token'); token.value=''; me.value=null; unreadCount.value=0; pendingProduct.value=null; selected.value=null; address.value={contact_name:'',contact_phone:'',province:'',city:'',district:'',detail:''}; transfer.value={phone:'',amount:'',password:''}; withdrawal.value={amount:'',account_name:'',alipay_account:'',password:''}; withdrawals.value=[]; earnings.value={total_reward:'0.00'}; alipayStatus.value={masked:''}; form.value.password=''; form.value.alipay_account=''; addresses.value=[]; orders.value=[]; transactions.value=[]; team.value=[]; addressId.value=''; qr.value=''; tab.value='shop' }
function openTab(value) { if(tab.value==='addresses' && value!=='addresses')pendingProduct.value=null; if (value !== 'shop' && !token.value) { tab.value='login'; return } tab.value=value; if (value === 'team') makeQr() }
async function makeQr() { if (!me.value?.invite_code) return; const link = `${location.origin}/#/login?transfer_invite=${me.value.invite_code}`; qr.value = await QRCode.toDataURL(link, { width: 220, margin: 1 }) }
async function copyInvite() { const link = `${location.origin}/#/login?transfer_invite=${me.value.invite_code}`; try { await navigator.clipboard.writeText(link); notify('邀请链接已复制') } catch { window.prompt('复制邀请链接', link) } }
function openPurchaseAddress(){if(!token.value){pendingProduct.value=null;selected.value=null;tab.value='login';return}pendingProduct.value=selected.value;selected.value=null;openTab('addresses')}
function returnFromAddress(){if(pendingProduct.value){selected.value=pendingProduct.value;pendingProduct.value=null;tab.value='shop'}else tab.value='profile'}
async function saveAddress() { try { if(address.value.detail.length>500) throw new Error('收货地址不能超过 500 字'); await api('/addresses'+(address.value.id?'/'+address.value.id:''), {method:address.value.id?'PUT':'POST',body:address.value}); notify('地址已保存'); address.value={contact_name:'',contact_phone:'',province:'',city:'',district:'',detail:''}; await refresh(); if(pendingProduct.value)returnFromAddress() } catch(e) { notify(e) } }
async function purchase() { if(busy.value)return; if(!addressId.value){openPurchaseAddress();notify('请先填写收货地址');return} busy.value=true; try { await api('/purchases',{method:'POST',body:{product_id:selected.value.id,address_id:Number(addressId.value),variant:variant.value,request_id:purchaseId.value}}); purchaseId.value=crypto.randomUUID(); selected.value=null; notify('购买成功'); await refresh(); tab.value='orders' } catch(e) { notify(e) } finally { busy.value=false } }
async function send() { if(busy.value)return; busy.value=true; try { await api('/transfer',{method:'POST',body:{...transfer.value,request_id:transferId.value}}); transferId.value=crypto.randomUUID(); transfer.value={phone:'',amount:'',password:''}; notify('转赠成功'); await refresh() } catch(e) { notify(e) } finally { busy.value=false } }
async function openWithdrawal(){tab.value='withdrawal';try{[withdrawals.value,alipayStatus.value]=await Promise.all([api('/withdrawals'),api('/account/alipay')])}catch(e){notify(e)}}
async function applyWithdrawal(){if(busy.value)return;if(!withdrawalPreview.value){notify('提现金额至少 50，且须为 50 的整数倍');return}const account=withdrawal.value.alipay_account.trim(), masked=account?'****'+account.slice(-4):alipayStatus.value.masked;if(!masked||!withdrawal.value.account_name.trim()){notify('请填写支付宝账号和收款人');return}if(!confirm(`确认提现 ${withdrawal.value.amount} 产品券，预计到账 ${withdrawalPreview.value.net} 元？\n收款人：${withdrawal.value.account_name}\n支付宝账号：${masked}`))return;busy.value=true;try{await api('/withdrawals',{method:'POST',body:{...withdrawal.value,request_id:withdrawalId.value}});withdrawalId.value=crypto.randomUUID();withdrawal.value={amount:'',account_name:'',alipay_account:'',password:''};await refresh();notify('提现申请已提交，等待审核')}catch(e){notify(e)}finally{busy.value=false}}
async function changeName() { const username = prompt('新用户名', me.value?.username); if (!username) return; try { await api('/account',{method:'PUT',body:{username}}); await refresh(); notify('用户名已修改') } catch(e) { notify(e) } }
async function changePassword() { const old_password = prompt('请输入原密码'); if (!old_password) return; const new_password = prompt('请输入新密码'); if (!new_password) return; try { await api('/account',{method:'PUT',body:{old_password,new_password}}); notify('密码已修改') } catch(e) { notify(e) } }
async function deleteAddress(id) { if (!confirm('删除此地址？')) return; try { await api('/addresses/'+id,{method:'DELETE'}); await refresh(); notify('地址已删除') } catch(e) { notify(e) } }
function editAddress(a) { address.value={...a,province:'',city:'',district:'',detail:[a.province,a.city,a.district,a.detail].filter(Boolean).join(' ')} }
function options(p) { try { return typeof p.options === 'string' ? JSON.parse(p.options) : (p.options || []) } catch { return [] } }
function detailImages(p) { try { return typeof p.detail_images === 'string' ? JSON.parse(p.detail_images) : (p.detail_images || []) } catch { return [] } }
let noticeTimer
onMounted(() => { refresh(); noticeTimer=setInterval(refreshNotices, 30000) })
onUnmounted(() => clearInterval(noticeTimer))
</script>
<template>
  <div class="app"><div v-if="message" class="toast">{{ message }}</div>
    <header class="top"><div><small>LOCAL COMMERCE</small><h1>本地商圈</h1></div><button class="top-btn" @click="openTab('profile')">{{ me ? me.username : '登录 / 注册' }}</button></header>
    <main :class="{ 'shop-main': tab === 'shop' }">
      <template v-if="tab === 'shop'"><section class="hero hero-reference" aria-label="品质生活 · 智慧商圈，发现身边的好物"><img src="./assets/storefront-reference.png" alt="" aria-hidden="true"></section><div class="section-title"><div><h2>商圈精选</h2><p>用产品券兑换心仪好物</p></div><span>{{ filteredProducts.length }} 件商品</span></div><div class="category-list" aria-label="商品分类"><button v-for="item in categories" :key="item.value" :class="{active: category===item.value}" @click="category=item.value">{{ item.label }}</button></div><div class="grid"><article class="product" v-for="p in filteredProducts" :key="p.id" @click="selected=p; variant='' "><img v-if="p.image" :src="p.image" :alt="p.name"><div v-else class="product-placeholder">✿</div><div class="product-body"><b>{{ p.name }}</b><p>{{ p.description || '精选品质好物' }}</p><strong>{{ p.cost }} <small>产品券</small></strong><div class="product-foot"><span>收益 {{ p.reward }} 券</span><span>库存 {{ p.stock }}</span></div></div></article></div><div v-if="!filteredProducts.length" class="empty">该分类暂无商品</div></template>
      <template v-if="tab === 'login'"><section class="card form"><h2>{{ mode==='login'?'欢迎回来':'加入本地商圈' }}</h2><p> {{ mode==='login'?'登录后查看您的商圈':'使用推荐人的邀请码注册' }}</p><input v-model="form.phone" placeholder="手机号" type="tel"><input v-if="mode==='register'" v-model="form.username" placeholder="用户名"><input v-model="form.password" placeholder="密码" type="password"><input v-if="mode==='register'" v-model.trim="form.alipay_account" placeholder="支付宝账号"><input v-if="mode==='register'" v-model="form.invite_code" placeholder="商圈邀请码"><button class="primary" @click="login">{{ mode==='login'?'登录':'注册' }}</button><button class="link" @click="mode=mode==='login'?'register':'login'">{{ mode==='login'?'没有账号？立即注册':'已有账号？返回登录' }}</button></section></template>
      <template v-if="tab === 'team'"><section class="card team-hero"><small>我的智慧商圈</small><h2>{{ team.reduce((n,x)=>n+Number(x.count),0) }} <small>位成员</small></h2><p>已拓展 {{ team.length }} 个成员分组 · 我的复购 {{ me?.purchase_count ?? 0 }} 次</p><p>累计商圈收益 <b>{{ earnings.total_reward }} 产品券</b></p><button class="outline" @click="openWithdrawal">申请提现</button></section><section class="card"><h3>邀请新成员</h3><p>专属邀请码 <b>{{ me?.invite_code || '不可邀请' }}</b></p><img v-if="qr" class="qr" :src="qr" alt="商圈邀请二维码"><button v-if="qr" class="outline" @click="copyInvite">复制邀请链接</button></section><section class="card"><h3>成员分组</h3><div v-for="row in team" :key="row.depth" class="list-row"><span>第 {{ row.depth }} 组</span><b>{{ row.count }} 人</b></div><p v-if="!team.length" class="muted">暂无成员</p></section></template>
      <template v-if="tab === 'orders'"><h2>我的订单</h2><article v-for="o in orders" :key="o.id" class="card order"><img v-if="o.product_image" class="order-image" :src="o.product_image" :alt="o.product_name"><div v-else class="order-image order-placeholder" aria-label="暂无商品图片">✿</div><div class="list-row"><b>{{ o.product_name }}</b><span class="badge">{{ o.received_at ? '已收货' : (o.pickup_code ? '待收货' : '待到货') }}</span></div><p>订单号 {{ o.order_no }}</p><p>购买 {{ o.cost }} 券 · 第 {{ o.purchase_sequence }} 次</p><p v-if="o.variant">款式：{{ o.variant }}</p><button v-if="o.pickup_code" class="notice" @click="readNotice(o)"><span v-if="isUnreadNotice(o)" class="notice-dot" aria-label="未读"></span>到货提醒：提货码 {{ o.pickup_code }} {{ o.pickup_message }}</button><button v-if="o.pickup_code && !o.received_at && o.status !== 'cancelled'" class="outline" :disabled="busy" @click="confirmReceipt(o)">确认收货</button></article><div v-if="!orders.length" class="empty">暂无订单</div></template>
      <template v-if="tab === 'profile'"><section class="card profile"><small>我的账户</small><h2>{{ me?.username }}</h2><p>{{ me?.phone }}</p><div class="balance"><span>产品券余额</span><strong>{{ me?.balance }}</strong><small>复购 {{ me?.purchase_count }} 次</small></div></section><div class="actions"><button @click="openWithdrawal">申请提现 <span>›</span></button><button @click="tab='transfer'">产品券转赠 <span>›</span></button><button @click="tab='addresses'">收货地址 <span>›</span></button><button @click="tab='records'">产品券明细 <span>›</span></button><button @click="changeName">修改用户名 <span>›</span></button><button @click="changePassword">修改密码 <span>›</span></button><button @click="logout">退出登录 <span>›</span></button></div></template>
      <template v-if="tab === 'withdrawal'"><section class="card form"><h2>申请提现</h2><p>产品券余额 {{ me?.balance }}；最低 50，按 50 的整数倍申请，手续费 6%。</p><input v-model="withdrawal.amount" type="number" min="50" step="50" placeholder="提现产品券数量"><p v-if="withdrawalPreview">手续费 {{ withdrawalPreview.fee }}，预计到账 {{ withdrawalPreview.net }} 元</p><input v-model.trim="withdrawal.account_name" placeholder="支付宝收款人姓名"><p v-if="alipayStatus.masked">已保存的支付宝账号：{{ alipayStatus.masked }}。留空将使用该账号。</p><input v-model.trim="withdrawal.alipay_account" placeholder="支付宝账号（已注册可留空）"><input v-model="withdrawal.password" type="password" placeholder="登录密码"><button class="primary" :disabled="busy" @click="applyWithdrawal">提交提现申请</button><button class="link" @click="tab='profile'">返回</button></section><section class="card"><h3>提现记录</h3><div v-for="item in withdrawals" :key="item.id" class="address"><b>申请 {{ item.amount }} · 到账 {{ item.net }} 元</b><p>{{ {pending:'待审核',approved:'已审核，等待转账',paid:'已转账',rejected:'已驳回'}[item.status] }}<span v-if="item.reason"> · {{ item.reason }}</span></p><p>手续费 {{ item.fee }} · 支付宝 {{ item.account_number }}</p><p v-if="item.transfer_note">转账记录：{{ item.transfer_note }}</p><ProofThumb v-if="item.has_proof" :id="item.id" :token="token" /></div><p v-if="!withdrawals.length" class="muted">暂无提现记录</p></section></template>
      <template v-if="tab === 'transfer'"><section class="card form"><h2>产品券转赠</h2><p>余额 {{ me?.balance }} 产品券，按整数原额转赠</p><input v-model="transfer.phone" placeholder="收款人手机号" type="tel"><input v-model="transfer.amount" placeholder="转赠数量" type="number"><input v-model="transfer.password" placeholder="登录密码" type="password"><button class="primary" @click="send">确认转赠</button><button class="link" @click="tab='profile'">返回</button></section></template>
      <template v-if="tab === 'addresses'"><section class="card form"><h2>收货地址</h2><div v-for="a in addresses" :key="a.id" class="address"><b>{{ a.contact_name }} {{ a.contact_phone }}</b><p>{{ a.province }} {{ a.city }} {{ a.district }} {{ a.detail }}</p><button class="link" @click="editAddress(a)">编辑</button><button class="link" @click="deleteAddress(a.id)">删除</button></div><h3>{{ address.id?'编辑地址':'新增默认地址' }}</h3><input v-model="address.contact_name" placeholder="收货人"><input v-model="address.contact_phone" placeholder="手机号"><input v-model="address.detail" placeholder="请输入完整收货地址"><button class="primary" @click="saveAddress">保存地址</button><button class="link" @click="returnFromAddress">返回</button></section></template>
      <template v-if="tab === 'records'"><section class="card"><h2>产品券明细</h2><div v-for="item in transactions" :key="item.id" class="list-row"><div><b>{{ item.description }}</b><p>{{ item.created_at?.slice(0,10) }}</p></div><strong>{{ item.amount }}</strong></div><p v-if="!transactions.length" class="muted">暂无记录</p><button class="link" @click="tab='profile'">返回</button></section></template>
    </main><nav class="bottom"><button @click="openTab('shop')" :class="{active:tab==='shop'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10h18l-1.6-5H4.6L3 10Zm1 0v9h16v-9M8 19v-5h8v5"/></svg><small>商圈</small></button><button @click="openTab('team')" :class="{active:tab==='team'}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="3"/><path d="M3 19v-1a6 6 0 0 1 12 0v1H3ZM16 5a3 3 0 0 1 0 6m1 2a5 5 0 0 1 4 5v1h-3"/></svg><small>团队</small></button><button @click="openTab('orders')" :class="{active:tab==='orders'}"><span class="nav-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M8 10h8M8 14h8M8 18h5"/></svg><i v-if="unreadCount" class="nav-dot" :aria-label="`${unreadCount}条未读到货提醒`"></i></span><small>订单</small></button><button @click="openTab('profile')" :class="{active:tab==='profile'}"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 21v-1a8 8 0 0 1 16 0v1H4Z"/></svg><small>我的</small></button></nav>
    <div v-if="selected" class="overlay" @click.self="selected=null"><div class="sheet"><button class="close" @click="selected=null">×</button><img v-if="selected.image" class="detail-img" :src="selected.image"><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p><h3>{{ selected.cost }} 产品券</h3><p>固定收益 {{ selected.reward }} 券 · 库存 {{ selected.stock }}</p><select v-if="options(selected).length" v-model="variant"><option value="">请选择款式</option><option v-for="o in options(selected)" :key="o.id" :value="o.id">{{ o.label }}</option></select><select v-model="addressId"><option value="">请选择收货地址</option><option v-for="a in addresses" :key="a.id" :value="a.id">{{ a.contact_name }} {{ [a.province,a.city,a.district,a.detail].filter(Boolean).join(' ') }}</option></select><button class="link" @click="openPurchaseAddress">{{ addresses.length ? '管理收货地址' : '填写收货地址' }}</button><button class="primary" :disabled="busy || Boolean(me?.is_root)" @click="token ? purchase() : (selected=null,tab='login')">{{ !token ? '登录后购买' : (me?.is_root ? '根账户不能购买' : '确认购买') }}</button><img v-for="url in detailImages(selected)" :key="url" class="detail-img" :src="url" alt="商品详情"></div></div>
  </div>
</template>
